<style>
.app-dashboard .dash-chart{border:0;padding:0;box-shadow:none;background:transparent!important;border-radius:0}

.app-dashboard{max-width:1440px;margin-inline:auto;--dash-line:var(--theme-divider-border-color)}
.app-dashboard .app-dashboard-board{gap:24px}.app-dashboard [data-dashboard-id="app-publishing.summary"]{grid-column:1/-1}
@media(min-width:1100px){.app-dashboard [data-dashboard-id="app-channels.summary"],.app-dashboard [data-dashboard-id]:has(.dash-ai-panel){grid-column:span 6}}
.app-dashboard .dash-hero{position:relative;isolation:isolate;overflow:hidden;padding:32px 36px;border-radius:20px;background:var(--theme-surface-base);border:1px solid var(--theme-card-border-color);grid-template-columns:minmax(0,1fr) 290px;gap:40px;align-items:center}
.dash-hero:before{content:"";position:absolute;z-index:-1;right:180px;top:-150px;width:520px;height:520px;border-radius:50%;background:radial-gradient(circle,rgba(var(--theme-accent-rgb),.10),transparent 67%);pointer-events:none}
.app-dashboard .sp-welcome-main h1{font-size:38px;line-height:1.13;max-width:650px;letter-spacing:-1.5px;margin:12px 0 14px;font-weight:650;text-wrap:balance}
.app-dashboard .sp-welcome-main>p{font-size:14px}.app-dashboard .sp-dashboard-kicker{color:var(--theme-accent);font-size:12px;font-weight:600}
.app-dashboard .sp-welcome-plan{margin:16px 0}.app-dashboard .sp-dashboard-actions{display:flex;gap:10px;flex-wrap:wrap}
.app-dashboard .sp-credit-card{background:#123f38;color:#fff;border:0;border-radius:16px;padding:24px;box-shadow:0 14px 30px -20px rgba(9,57,49,.55)}
.app-dashboard .sp-credit-top,.app-dashboard .sp-credit-detail{color:#c1ddd6}.app-dashboard .sp-credit-balance{font-size:48px;color:#fff;margin:16px 0;letter-spacing:-2px}.app-dashboard .sp-credit-progress{background:#31594f;height:5px;margin:16px 0}.app-dashboard .sp-credit-progress>div{background:#8edbc9}
.dash-section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:22px}.dash-section-heading h2{font-size:22px;line-height:1.3;font-weight:650;letter-spacing:-.65px;color:var(--theme-header-text-color);margin:4px 0}.dash-section-heading h3{font-size:16px;font-weight:650;letter-spacing:-.3px}.dash-section-heading p,.dash-muted{font-size:12px;color:var(--theme-muted-text-color);line-height:1.6;margin-top:5px}.dash-kicker{font-size:11px;color:var(--theme-accent);font-weight:600;letter-spacing:.6px}.dash-link{font-size:12px;font-weight:600;color:var(--theme-accent);display:inline-flex;align-items:center;gap:8px}.dash-link:hover{text-decoration:underline}
.dash-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:24px}.dash-stat{padding:21px 24px;border:1px solid var(--theme-card-border-color);border-radius:14px;background:var(--theme-surface-base)}.dash-stat>div{display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--theme-muted-text-color)}.dash-stat i{font-size:18px}.dash-stat>strong{display:block;font-size:38px;line-height:1.15;font-weight:650;letter-spacing:-1.5px;margin:16px 0 8px}.dash-stat p{font-size:11px;color:var(--theme-muted-text-color)}
.dash-publishing-grid{display:grid;grid-template-columns:1.05fr 1fr;gap:24px}.dash-panel{padding:26px;border-radius:var(--theme-card-radius,16px);border:1px solid var(--theme-card-border-color);background:var(--theme-surface-base);height:100%;min-width:0}.dash-pill{display:inline-flex;padding:5px 9px;border-radius:6px;background:var(--sp-nav-active);color:var(--theme-accent);font-size:10px;font-weight:600;white-space:nowrap}
.dash-publishing>.sp-metric-strip--portal{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:24px}
.dash-empty{display:flex;min-height:238px;align-items:center;justify-content:center;flex-direction:column;text-align:center;background:linear-gradient(140deg,rgba(var(--theme-accent-rgb),.035),transparent);border:1px dashed var(--theme-border-color);border-radius:12px;padding:24px;margin:0 0 18px}.dash-empty-icon{display:grid;place-items:center;width:50px;height:50px;border-radius:14px;background:var(--sp-nav-active);color:var(--theme-accent);font-size:23px;margin-bottom:14px}.dash-empty h3{font-size:17px;font-weight:600}.dash-empty p{max-width:340px;font-size:12px;line-height:1.7;color:var(--theme-muted-text-color);margin:8px 0 14px}
.dash-foot{border-top:1px solid var(--dash-line);padding-top:16px;margin-top:18px;display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;font-size:11px;color:var(--theme-muted-text-color)}.dash-foot strong{color:var(--theme-header-text-color)}
.dash-post{display:flex;align-items:center;gap:12px;padding:18px 0;border-bottom:1px solid var(--dash-line)}.dash-post:hover .dash-post-copy strong{color:var(--theme-accent)}.dash-post-icon{display:grid;place-items:center;width:42px;height:46px;border-radius:9px;background:var(--theme-surface-soft);color:var(--theme-accent);flex-shrink:0}.dash-post-copy{min-width:0;flex:1}.dash-post-copy strong{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px;font-weight:600}.dash-post-copy small{display:block;font-size:10px;color:var(--theme-muted-text-color);margin-top:6px}
.dash-shortcuts{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.dash-shortcuts a{padding:8px 12px;border-radius:7px;border:1px solid var(--dash-line);font-size:11px;display:flex;align-items:center;gap:8px}.dash-shortcuts a:hover{background:var(--sp-nav-active);color:var(--theme-accent)}
.dash-network-total{display:flex;align-items:center;gap:16px;margin:24px 0}.dash-network-total>strong{font-size:54px;letter-spacing:-2px;font-weight:600;line-height:1}.dash-network-total>span{font-size:14px}.dash-network-total small{display:block;font-size:11px;color:var(--theme-muted-text-color);margin-top:6px}.dash-provider-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px 18px}.dash-provider-grid>div{font-size:11px}.dash-provider-grid strong{float:right}.dash-meter{height:4px;border-radius:9px;background:var(--theme-surface-soft);margin-top:9px;overflow:hidden}.dash-meter span{height:100%;display:block;background:var(--theme-accent);border-radius:9px}
.dash-ai-panel{background:linear-gradient(145deg,rgba(var(--theme-accent-rgb),.045),transparent 65%),var(--theme-surface-base)}.dash-ai-panel .dash-section-heading{margin-bottom:10px}.dash-ai-mark{font-size:27px;color:var(--theme-accent)}.dash-ai-tools{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:24px 0 16px}.dash-ai-tools a{display:flex;align-items:center;gap:10px;border:1px solid var(--theme-card-border-color);background:var(--theme-surface-base);border-radius:11px;padding:14px}.dash-ai-tools a>span{display:grid;place-items:center;width:34px;height:34px;border-radius:9px;color:var(--theme-accent);background:var(--sp-nav-active)}.dash-ai-tools strong{font-size:12px;font-weight:600;flex:1}.dash-ai-tools a>i{font-size:11px;color:var(--theme-muted-text-color)}.dash-ai-tools a:hover{border-color:var(--theme-accent)}.dash-ai-more summary{font-size:12px;color:var(--theme-accent);cursor:pointer}.dash-bars{display:flex;gap:16px;height:238px;padding:12px 0 18px}.dash-bars>div{flex:1;text-align:center;display:flex;flex-direction:column;gap:8px;font-size:11px}.dash-bar-track{flex:1;display:flex;align-items:flex-end;border-bottom:1px solid var(--dash-line)}.dash-bar-track span{width:100%;background:var(--theme-accent);border-radius:6px 6px 0 0}.dash-bars small{color:var(--theme-muted-text-color)}
@media(max-width:1099px){.app-dashboard .dash-hero{grid-template-columns:1fr 250px;padding:26px;gap:24px}.app-dashboard .sp-welcome-main h1{font-size:30px}.dash-publishing>.sp-metric-strip--portal{grid-template-columns:repeat(2,minmax(0,1fr))}.dash-publishing-grid{grid-template-columns:1fr}.dash-section-heading{flex-wrap:wrap}.dash-stats{gap:12px}.dash-stat{padding:18px}}
@media(max-width:639px){.app-dashboard .dash-hero{grid-template-columns:1fr;padding:22px;gap:22px;border-radius:14px}.app-dashboard .sp-welcome-main h1{font-size:29px}.app-dashboard .sp-credit-card{padding:18px}.app-dashboard .sp-credit-balance{font-size:36px;margin:10px 0}.dash-stats{grid-template-columns:1fr 1fr}.dash-stat>strong{font-size:30px}.dash-panel{padding:20px}.dash-section-heading h2{font-size:20px}.dash-provider-grid{grid-template-columns:1fr 1fr}.dash-ai-tools{grid-template-columns:1fr}.dash-post{flex-wrap:wrap}.dash-post .dash-pill{margin-left:54px}.dash-empty{min-height:220px}.app-dashboard .app-dashboard-board{gap:20px}}
@media(prefers-reduced-motion:no-preference){.dash-ai-tools a,.dash-stat{transition:border-color .15s,background-color .15s}}

.dash-report-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:36px 0 20px}.dash-report-heading h2{font-size:25px;font-weight:650;letter-spacing:-.6px;margin:5px 0}.dash-report-heading p{font-size:12px;color:var(--theme-muted-text-color)}
.dash-report-alerts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:24px}.dash-report-alerts>a{display:flex;align-items:center;gap:16px;padding:22px;background:var(--theme-surface-base);border:1px solid var(--theme-card-border-color);border-radius:14px}.dash-report-alerts>a>i{margin-left:auto;color:var(--theme-muted-text-color)}.dash-report-alerts strong{font-size:30px;line-height:1.1;font-weight:650;display:block}.dash-report-alerts span:not(.dash-alert-icon){font-size:12px;display:block;margin-top:5px}.dash-report-alerts small{display:block;font-size:10px;margin-top:5px;color:var(--theme-muted-text-color)}.dash-alert-icon{width:40px;height:40px;display:grid;place-items:center;background:var(--sp-nav-active);color:var(--theme-accent);border-radius:10px}
.dash-report-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.dash-report-wide{grid-column:span 2}.dash-report-empty{min-height:200px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:16px;font-size:12px;color:var(--theme-muted-text-color)}.dash-report-empty>i{font-size:28px;color:var(--theme-accent)}.dash-report-table{overflow-x:auto;min-height:220px}.dash-report-table table{width:100%;font-size:12px;text-align:left;border-collapse:collapse}.dash-report-table th{font-size:11px;font-weight:500;color:var(--theme-muted-text-color);white-space:nowrap}.dash-report-table th,.dash-report-table td{padding:12px 8px;border-bottom:1px solid var(--dash-line)}.dash-upcoming{display:flex;flex-direction:column;gap:5px;padding:12px 0;border-bottom:1px solid var(--dash-line)}.dash-upcoming small{font-size:10px;color:var(--theme-accent)}.dash-upcoming strong{font-size:12px;font-weight:600}.dash-upcoming span{font-size:11px;color:var(--theme-muted-text-color)}.dash-rank{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--dash-line);font-size:12px}
@media(max-width:1099px){.dash-report-grid{grid-template-columns:1fr 1fr}.dash-report-wide{grid-column:span 2}.dash-report-alerts>a{padding:16px;gap:10px}.dash-alert-icon{display:none}}
@media(max-width:639px){.dash-report-grid{grid-template-columns:1fr}.dash-report-wide{grid-column:auto}.dash-report-alerts{grid-template-columns:1fr}.dash-report-heading{align-items:flex-start;flex-direction:column}.dash-report-alerts>a>div{display:grid;grid-template-columns:45px 1fr;column-gap:12px;align-items:center}.dash-report-alerts strong{grid-row:span 2}.dash-report-alerts small{grid-column:2}.dash-report-alerts span:not(.dash-alert-icon){margin:0}}
.dash-report-period{display:flex;gap:10px;align-items:center;font-size:12px;color:var(--theme-muted-text-color)}.dash-report-period select{padding:9px 30px 9px 12px;border:1px solid var(--theme-border-color);border-radius:8px;background:var(--theme-surface-base);color:var(--theme-header-text-color)}
.dash-attention{margin-bottom:32px}.dash-attention .dash-section-heading{margin-bottom:16px}.dash-attention .dash-report-alerts{margin-bottom:0}
.dash-attention-warning{--dash-action:#a76c15}.dash-attention-danger{--dash-action:#c24141}.dash-attention-warning .dash-alert-icon,.dash-attention-danger .dash-alert-icon{color:var(--dash-action);background:color-mix(in srgb,var(--dash-action) 10%,var(--theme-surface-base))}.dash-report-alerts>a:hover{border-color:var(--dash-action,var(--theme-accent))}.dash-report-alerts>a:focus-visible{outline:2px solid var(--theme-accent);outline-offset:3px}
.dash-run-status{display:grid;gap:7px;padding:13px;margin-top:14px;border:1px solid var(--theme-card-border-color);border-radius:10px;font-size:11px;color:var(--theme-muted-text-color);line-height:1.6}.dash-run-status strong{color:var(--theme-header-text-color);font-size:12px}.dash-run-status.is-overdue{border-color:color-mix(in srgb,#c38b2b 35%,var(--theme-card-border-color));background:color-mix(in srgb,#c38b2b 5%,var(--theme-surface-base))}.dash-run-status.is-overdue strong{color:#a76c15}.dark .dash-run-status.is-overdue strong{color:#e7b963}
</style>
